19	// Shadow strategy session state methods.
20	// Uses session.StateStore for persistence.
21	
22	// loadSessionState loads session state using the StateStore.
23	func (s *ManualCommitStrategy) loadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
24		store, err := s.getStateStore(ctx)
25		if err != nil {
26			return nil, err
27		}
28		state, err := store.Load(ctx, sessionID)
29		if err != nil {
30			return nil, fmt.Errorf("failed to load session state: %w", err)
31		}
32		return state, nil
33	}
34	
35	// saveSessionState saves session state using the StateStore.
36	func (s *ManualCommitStrategy) saveSessionState(ctx context.Context, state *SessionState) error {
37		store, err := s.getStateStore(ctx)
38		if err != nil {
39			return err
40		}
41		if err := store.Save(ctx, state); err != nil {
42			return fmt.Errorf("failed to save session state: %w", err)
43		}
44		return nil
45	}
