47	// clearSessionState clears session state using the StateStore.
48	func (s *ManualCommitStrategy) clearSessionState(ctx context.Context, sessionID string) error {
49		store, err := s.getStateStore(ctx)
50		if err != nil {
51			return err
52		}
53		if err := store.Clear(ctx, sessionID); err != nil {
54			return fmt.Errorf("failed to clear session state: %w", err)
55		}
56		return nil
57	}
