59	// listAllSessionStates returns all active session states.
60	// It filters out orphaned sessions whose shadow branch no longer exists.
61	func (s *ManualCommitStrategy) listAllSessionStates(ctx context.Context) ([]*SessionState, error) {
62		store, err := s.getStateStore(ctx)
63		if err != nil {
64			return nil, fmt.Errorf("failed to get state store: %w", err)
65		}
66	
67		sessionStates, err := store.List(ctx)
68		if err != nil {
69			return nil, fmt.Errorf("failed to list session states: %w", err)
70		}
71	
72		if len(sessionStates) == 0 {
73			return nil, nil
74		}
75	
76		repo, err := OpenRepository(ctx)
77		if err != nil {
78			return nil, fmt.Errorf("failed to open git repository: %w", err)
79		}
80	
81		var states []*SessionState
82		for _, sessionState := range sessionStates {
83			state := sessionState
84	
85			// Skip and cleanup orphaned sessions whose shadow branch no longer exists.
86			// Keep active sessions (shadow branch may not be created yet) and sessions
87			// with LastCheckpointID (needed for checkpoint ID reuse on subsequent commits).
88			// Clean up everything else: stale pre-state-machine sessions (empty phase),
89			// IDLE/ENDED sessions that were never condensed, etc.
90			shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
91			refName := plumbing.NewBranchReferenceName(shadowBranch)
92			if _, err := repo.Reference(refName, true); err != nil {
93				if !state.Phase.IsActive() && state.LastCheckpointID.IsEmpty() {
94					//nolint:errcheck,gosec // G104: Cleanup is best-effort, shouldn't fail the list operation
95					store.Clear(ctx, state.SessionID)
96					continue
97				}
98			}
99	
100			states = append(states, state)
101		}
102		return states, nil
103	}
