135	// findSessionsForWorktree finds all sessions for the given worktree path.
136	//
137	// When invoked from a linked worktree (where the current worktree differs from
138	// the main worktree resolved via git --git-common-dir), sessions registered
139	// against the main worktree are also returned. Agent-managed worktrees — like
140	// Claude Code's .claude/worktrees/<branch> feature — spawn a sub-process that
141	// inherits a session whose UserPromptSubmit fired in the main worktree; the
142	// hook handler must still be able to find that session when prepare-commit-msg
143	// / post-commit / etc. run from inside the linked worktree at commit time.
144	//
145	// Sessions registered against unrelated linked worktrees (e.g. a sibling
146	// worktree) are never returned: the widening is one-directional (linked →
147	// main), so commits in worktree A don't pick up sessions from worktree B.
148	// From the main worktree, behavior is unchanged: only sessions whose
149	// WorktreePath equals the main path are returned.
150	func (s *ManualCommitStrategy) findSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
151		allStates, err := s.listAllSessionStates(ctx)
152		if err != nil {
153			return nil, err
154		}
155	
156		// Resolve the main worktree path to decide whether to widen the match.
157		// Failure to resolve degrades gracefully to exact match — i.e. the prior
158		// behavior — so this fallback can't make any caller worse off.
159		mainPath := ""
160		if p, mainErr := paths.MainWorktreeRoot(ctx); mainErr == nil {
161			mainPath = p
162		}
163		widenToMain := mainPath != "" && mainPath != worktreePath
164	
165		var matching []*SessionState
166		for _, state := range allStates {
167			if state.WorktreePath == worktreePath {
168				matching = append(matching, state)
169				continue
170			}
171			if widenToMain && state.WorktreePath == mainPath {
172				matching = append(matching, state)
173			}
174		}
175		return matching, nil
176	}
