178	type rewritePair struct {
179		OldSHA string
180		NewSHA string
181	}
182	
183	func remapRewriteSHA(sha string, rewrites []rewritePair) (string, bool) {
184		for _, pair := range rewrites {
185			if sha == pair.OldSHA {
186				return pair.NewSHA, true
187			}
188		}
189		return sha, false
190	}
