192	func shadowBranchExistsForBaseCommit(repo *git.Repository, baseCommit, worktreeID string) bool {
193		if repo == nil || baseCommit == "" {
194			return false
195		}
196	
197		refName := plumbing.NewBranchReferenceName(checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID))
198		_, err := repo.Reference(refName, true)
199		return err == nil
200	}
201	
202	func (s *ManualCommitStrategy) remapSessionForRewrite(ctx context.Context, repo *git.Repository, state *SessionState, rewrites []rewritePair) (bool, error) {
203		if state == nil {
204			return false, nil
205		}
206	
207		newBaseCommit, baseChanged := remapRewriteSHA(state.BaseCommit, rewrites)
208		newAttrBaseCommit, attrChanged := remapRewriteSHA(state.AttributionBaseCommit, rewrites)
209		if !baseChanged && !attrChanged {
210			return false, nil
211		}
212	
213		hadShadowBranch := shadowBranchExistsForBaseCommit(repo, state.BaseCommit, state.WorktreeID)
214		if baseChanged {
215			changed, err := s.migrateShadowBranchToBaseCommit(ctx, repo, state, newBaseCommit)
216			if err != nil {
217				return false, fmt.Errorf("failed to migrate rewritten shadow branch: %w", err)
218			}
219			baseChanged = changed
220		}
221	
222		// If a shadow branch existed, preserve AttributionBaseCommit so future
223		// attribution still diffs against the original checkpoint base captured on
224		// that branch. Without a shadow branch, keep attribution in sync with the
225		// rewritten commit lineage.
226		if attrChanged && !hadShadowBranch {
227			state.AttributionBaseCommit = newAttrBaseCommit
228		}
229	
230		return baseChanged || attrChanged, nil
231	}
232	
233	// findSessionsForCommit finds all sessions where base_commit matches the given SHA.
234	func (s *ManualCommitStrategy) findSessionsForCommit(ctx context.Context, baseCommitSHA string) ([]*SessionState, error) {
235		allStates, err := s.listAllSessionStates(ctx)
236		if err != nil {
237			return nil, err
238		}
239	
240		var matching []*SessionState
241		for _, state := range allStates {
242			if state.BaseCommit == baseCommitSHA {
243				matching = append(matching, state)
244			}
245		}
246		return matching, nil
247	}
