261	// CountOtherActiveSessionsWithCheckpoints counts how many other active sessions
262	// from the SAME worktree (different from currentSessionID) have created checkpoints
263	// on the SAME base commit (current HEAD). This is used to show an informational message
264	// about concurrent sessions that will be included in the next commit.
265	// Returns 0, nil if no such sessions exist.
266	func (s *ManualCommitStrategy) CountOtherActiveSessionsWithCheckpoints(ctx context.Context, currentSessionID string) (int, error) {
267		currentWorktree, err := paths.WorktreeRoot(ctx)
268		if err != nil {
269			return 0, fmt.Errorf("failed to get worktree root: %w", err)
270		}
271	
272		// Get current HEAD to compare with session base commits
273		repo, err := OpenRepository(ctx)
274		if err != nil {
275			return 0, err
276		}
277		head, err := repo.Head()
278		if err != nil {
279			return 0, fmt.Errorf("failed to get HEAD: %w", err)
280		}
281		currentHead := head.Hash().String()
282	
283		allStates, err := s.listAllSessionStates(ctx)
284		if err != nil {
285			return 0, err
286		}
287	
288		count := 0
289		for _, state := range allStates {
290			// Only consider sessions from the same worktree with checkpoints
291			// AND based on the same commit (current HEAD)
292			// Sessions from different base commits are independent and shouldn't be counted
293			if state.SessionID != currentSessionID &&
294				state.WorktreePath == currentWorktree &&
295				state.StepCount > 0 &&
296				state.BaseCommit == currentHead {
297				count++
298			}
299		}
300		return count, nil
301	}
