303	// initializeSession creates a new session state or updates a partial one.
304	// A partial state may exist if the concurrent session warning was shown.
305	// agentType is the human-readable name of the agent (e.g., "Claude Code").
306	// transcriptPath is the path to the live transcript file (for mid-session commit detection).
307	// userPrompt is the user's prompt text (stored truncated as LastPrompt for display).
308	// model is the LLM model identifier (e.g., "claude-sonnet-4-20250514"); empty if unknown.
309	func (s *ManualCommitStrategy) initializeSession(ctx context.Context, repo *git.Repository, sessionID string, agentType types.AgentType, transcriptPath string, userPrompt string, model string) (*SessionState, error) {
310		head, err := repo.Head()
311		if err != nil {
312			return nil, fmt.Errorf("failed to get HEAD: %w", err)
313		}
314	
315		worktreePath, err := paths.WorktreeRoot(ctx)
316		if err != nil {
317			return nil, fmt.Errorf("failed to get worktree path: %w", err)
318		}
319	
320		// Get worktree ID for shadow branch naming
321		worktreeID, err := paths.GetWorktreeID(worktreePath)
322		if err != nil {
323			return nil, fmt.Errorf("failed to get worktree ID: %w", err)
324		}
325	
326		// Capture untracked files at session start to preserve them during rewind
327		untrackedFiles, err := collectUntrackedFiles(ctx)
328		if err != nil {
329			// Non-fatal: continue even if we can't collect untracked files
330			untrackedFiles = nil
331		}
332	
333		// Generate TurnID for the first turn
334		turnID, err := id.Generate()
335		if err != nil {
336			return nil, fmt.Errorf("failed to generate turn ID: %w", err)
337		}
338	
339		now := time.Now()
340		headHash := head.Hash().String()
341		state := &SessionState{
342			SessionID:             sessionID,
343			CLIVersion:            versioninfo.Version,
344			BaseCommit:            headHash,
345			AttributionBaseCommit: headHash,
346			WorktreePath:          worktreePath,
347			WorktreeID:            worktreeID,
348			StartedAt:             now,
349			LastInteractionTime:   &now,
350			TurnID:                turnID.String(),
351			StepCount:             0,
352			UntrackedFilesAtStart: untrackedFiles,
353			AgentType:             agentType,
354			ModelName:             model,
355			TranscriptPath:        transcriptPath,
356			LastPrompt:            truncatePromptForStorage(userPrompt),
357		}
358	
359		if err := s.saveSessionState(ctx, state); err != nil {
360			return nil, err
361		}
362	
363		return state, nil
364	}
