366	// getShadowBranchNameForCommit returns the shadow branch name for the given base commit and worktree ID.
367	// worktreeID should be empty for the main worktree or the internal git worktree name for linked worktrees.
368	func getShadowBranchNameForCommit(baseCommit, worktreeID string) string {
369		return checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID)
370	}
