12	// TestFindSessionsForWorktree_LinkedWorktreeMatchesMain verifies that a hook
13	// firing from inside a linked worktree (such as Claude Code's
14	// .claude/worktrees/<branch> agent feature) can still find sessions whose
15	// WorktreePath was registered against the main worktree.
16	//
17	// Regression coverage for the path where prepare-commit-msg / post-commit
18	// silently bail with "no active sessions" — strict path equality on
19	// WorktreePath was returning no matches because the session was created from
20	// the main worktree (where the user's prompt and UserPromptSubmit hook fired)
21	// but the commit fires from inside an agent-spawned linked worktree.
22	func TestFindSessionsForWorktree_LinkedWorktreeMatchesMain(t *testing.T) {
23		mainDir := t.TempDir()
24		// EvalSymlinks so /var → /private/var on macOS — git rev-parse returns the
25		// canonical form, and we need to compare like-for-like in the test below.
26		resolved, err := filepath.EvalSymlinks(mainDir)
27		if err != nil {
28			t.Fatalf("EvalSymlinks: %v", err)
29		}
30		mainDir = resolved
31		initTestRepo(t, mainDir)
32	
33		linkedDir := filepath.Join(mainDir, ".claude", "worktrees", "feature-x")
34		if err := createWorktree(mainDir, linkedDir, "feature-x"); err != nil {
35			t.Fatalf("createWorktree: %v", err)
36		}
37		t.Cleanup(func() { removeWorktree(mainDir, linkedDir) })
38	
39		t.Chdir(linkedDir)
40	
41		strat := NewManualCommitStrategy()
42		ctx := context.Background()
43	
44		// Active session registered against the MAIN worktree path. Phase=Active so
45		// listAllSessionStates doesn't prune it for lacking a shadow branch.
46		mainSession := &session.State{
47			SessionID:    "11111111-1111-1111-1111-111111111111",
48			BaseCommit:   "deadbeefdeadbeefdeadbeefdeadbeefdeadbeef",
49			WorktreePath: mainDir,
50			StartedAt:    time.Now(),
51			Phase:        session.PhaseActive,
52		}
53		if err := strat.saveSessionState(ctx, mainSession); err != nil {
54			t.Fatalf("saveSessionState (main): %v", err)
55		}
56	
57		// Session registered against an unrelated sibling worktree — must NOT
58		// match a commit firing from linkedDir.
59		siblingDir := filepath.Join(mainDir, ".claude", "worktrees", "sibling")
60		otherSession := &session.State{
61			SessionID:    "22222222-2222-2222-2222-222222222222",
62			BaseCommit:   "deadbeefdeadbeefdeadbeefdeadbeefdeadbeef",
63			WorktreePath: siblingDir,
64			StartedAt:    time.Now(),
65			Phase:        session.PhaseActive,
66		}
67		if err := strat.saveSessionState(ctx, otherSession); err != nil {
68			t.Fatalf("saveSessionState (sibling): %v", err)
69		}
70	
71		matched, err := strat.findSessionsForWorktree(ctx, linkedDir)
72		if err != nil {
73			t.Fatalf("findSessionsForWorktree: %v", err)
74		}
75	
76		gotIDs := map[string]bool{}
77		for _, s := range matched {
78			gotIDs[s.SessionID] = true
79		}
80		if !gotIDs[mainSession.SessionID] {
81			t.Errorf("expected main-worktree session %q to be returned from linked worktree, got %+v", mainSession.SessionID, gotIDs)
82		}
83		if gotIDs[otherSession.SessionID] {
84			t.Errorf("sibling-worktree session %q should NOT match from linked worktree %q", otherSession.SessionID, linkedDir)
85		}
86	}
87	
88	// TestFindSessionsForWorktree_MainWorktreeUnchanged verifies the widening is
89	// strictly one-directional: from the main worktree we must not start
90	// returning sessions whose WorktreePath points at a linked worktree.
91	// Otherwise a commit on main would silently pick up an unrelated agent
92	// session running in .claude/worktrees/<branch> and link the commit to it.
93	func TestFindSessionsForWorktree_MainWorktreeUnchanged(t *testing.T) {
94		mainDir := t.TempDir()
95		resolved, err := filepath.EvalSymlinks(mainDir)
96		if err != nil {
97			t.Fatalf("EvalSymlinks: %v", err)
98		}
99		mainDir = resolved
100		initTestRepo(t, mainDir)
101		t.Chdir(mainDir)
102	
103		strat := NewManualCommitStrategy()
104		ctx := context.Background()
105	
106		mainSession := &session.State{
107			SessionID:    "33333333-3333-3333-3333-333333333333",
108			BaseCommit:   "deadbeefdeadbeefdeadbeefdeadbeefdeadbeef",
109			WorktreePath: mainDir,
110			StartedAt:    time.Now(),
111			Phase:        session.PhaseActive,
112		}
113		if err := strat.saveSessionState(ctx, mainSession); err != nil {
114			t.Fatalf("saveSessionState (main): %v", err)
115		}
116	
117		linkedDir := filepath.Join(mainDir, ".claude", "worktrees", "feature-x")
118		linkedSession := &session.State{
119			SessionID:    "44444444-4444-4444-4444-444444444444",
120			BaseCommit:   "deadbeefdeadbeefdeadbeefdeadbeefdeadbeef",
121			WorktreePath: linkedDir,
122			StartedAt:    time.Now(),
123			Phase:        session.PhaseActive,
124		}
125		if err := strat.saveSessionState(ctx, linkedSession); err != nil {
126			t.Fatalf("saveSessionState (linked): %v", err)
127		}
128	
129		matched, err := strat.findSessionsForWorktree(ctx, mainDir)
130		if err != nil {
131			t.Fatalf("findSessionsForWorktree: %v", err)
132		}
133	
134		gotIDs := map[string]bool{}
135		for _, s := range matched {
136			gotIDs[s.SessionID] = true
137		}
138		if !gotIDs[mainSession.SessionID] {
139			t.Errorf("main-worktree session must be returned when looking up from main, got %+v", gotIDs)
140		}
141		if gotIDs[linkedSession.SessionID] {
142			t.Errorf("linked-worktree session %q must NOT bleed into main-worktree lookup, got %+v", linkedSession.SessionID, gotIDs)
143		}
144	}
