16	func TestParseHookEvent_SessionStart(t *testing.T) {
17		t.Parallel()
18	
19		ag := &ClaudeCodeAgent{}
20		input := `{"session_id": "test-session-123", "transcript_path": "/tmp/transcript.jsonl"}`
21	
22		event, err := ag.ParseHookEvent(context.Background(), HookNameSessionStart, strings.NewReader(input))
23	
24		if err != nil {
25			t.Fatalf("unexpected error: %v", err)
26		}
27		require.NotNil(t, event, "expected event, got nil")
28		if event.Type != agent.SessionStart {
29			t.Errorf("expected event type %v, got %v", agent.SessionStart, event.Type)
30		}
31		if event.SessionID != "test-session-123" {
32			t.Errorf("expected session_id 'test-session-123', got %q", event.SessionID)
33		}
34		if event.SessionRef != "/tmp/transcript.jsonl" {
35			t.Errorf("expected session_ref '/tmp/transcript.jsonl', got %q", event.SessionRef)
36		}
37		if event.Timestamp.IsZero() {
38			t.Error("expected non-zero timestamp")
39		}
40	}
