12	func TestIsSubpath(t *testing.T) {
13		tests := []struct {
14			name   string
15			parent string
16			child  string
17			want   bool
18		}{
19			// Basic containment
20			{name: "child inside parent", parent: "/a/b", child: "/a/b/c", want: true},
21			{name: "equal paths", parent: "/a/b", child: "/a/b", want: true},
22			{name: "child outside parent", parent: "/a/b", child: "/a/c", want: false},
23			{name: "parent prefix but not subpath", parent: "/a/b", child: "/a/bc", want: false},
24	
25			// Traversal attacks
26			{name: "dot-dot escape", parent: "/a/b", child: "/a/b/../../../etc/passwd", want: false},
27			{name: "dot-dot at end", parent: "/a/b", child: "/a/b/..", want: false},
28			{name: "dot-dot in middle", parent: "/a/b/c", child: "/a/b/c/../../d", want: false},
29	
30			// Relative paths
31			{name: "relative child inside", parent: ".entire", child: ".entire/metadata/test", want: true},
32			{name: "relative equal", parent: ".entire", child: ".entire", want: true},
33			{name: "relative outside", parent: ".entire", child: "src/main.go", want: false},
34			{name: "relative prefix not subpath", parent: ".entire", child: ".entirefile", want: false},
35	
36			// Edge cases
37			{name: "root parent", parent: "/", child: "/anything", want: true},
38			{name: "dot current dir", parent: ".", child: "foo/bar", want: true},
39		}
40	
41		for _, tt := range tests {
42			t.Run(tt.name, func(t *testing.T) {
43				got := IsSubpath(tt.parent, tt.child)
44				if got != tt.want {
45					t.Errorf("IsSubpath(%q, %q) = %v, want %v", tt.parent, tt.child, got, tt.want)
