232	// TestMainWorktreeRoot_LinkedWorktree verifies that when called from inside
233	// a linked worktree (e.g. Claude Code's agent-managed worktrees under
234	// .claude/worktrees/<branch>), MainWorktreeRoot returns the *main* repo's
235	// root, not the linked worktree root. Regression coverage for the case where
236	// git hooks fired from a linked worktree could not find .entire/settings.json
237	// and silently bailed.
238	func TestMainWorktreeRoot_LinkedWorktree(t *testing.T) {
239		if _, err := exec.LookPath("git"); err != nil {
240			t.Skip("git not available")
241		}
242	
243		mainRoot := initSeedRepo(t)
244		worktreeDir := filepath.Join(mainRoot, ".claude", "worktrees", "feature-x")
245		runGit(t, mainRoot, "worktree", "add", "-b", "feature-x", worktreeDir)
246	
247		t.Chdir(worktreeDir)
248		ClearWorktreeRootCache()
249	
250		got, err := MainWorktreeRoot(context.Background())
251		if err != nil {
252			t.Fatalf("MainWorktreeRoot from linked worktree: %v", err)
253		}
254	
255		if mustEvalSymlinks(t, got) != mustEvalSymlinks(t, mainRoot) {
256			t.Errorf("MainWorktreeRoot = %q, want main repo %q", got, mainRoot)
257		}
258	
259		// Sanity: ordinary WorktreeRoot from the same cwd points at the linked
260		// worktree, not the main repo. This is what makes the bug possible and
261		// why MainWorktreeRoot has to exist as a separate anchor.
262		wtRoot, err := WorktreeRoot(context.Background())
263		if err != nil {
264			t.Fatalf("WorktreeRoot: %v", err)
265		}
266		if mustEvalSymlinks(t, wtRoot) == mustEvalSymlinks(t, mainRoot) {
267			t.Errorf("WorktreeRoot from linked worktree (%q) should differ from main (%q); test setup may be wrong", wtRoot, mainRoot)
268		}
269	}
