271	// TestAbsPath_EntireAnchoredAtMainWorktree verifies that AbsPath resolves
272	// .entire/* paths against the main worktree root even when called from inside
273	// a linked worktree, while non-entire paths still resolve against the current
274	// worktree. This is the load-bearing assertion for the hook fix: without it,
275	// a hook firing from a Claude-managed worktree would fail the IsSetUp check
276	// (.entire/ does not exist in the worktree) and silently bail.
277	func TestAbsPath_EntireAnchoredAtMainWorktree(t *testing.T) {
278		if _, err := exec.LookPath("git"); err != nil {
279			t.Skip("git not available")
280		}
281	
282		mainRoot := initSeedRepo(t)
283		worktreeDir := filepath.Join(mainRoot, ".claude", "worktrees", "feature-x")
284		runGit(t, mainRoot, "worktree", "add", "-b", "feature-x", worktreeDir)
285	
286		t.Chdir(worktreeDir)
287		ClearWorktreeRootCache()
288	
289		ctx := context.Background()
290	
291		// Pre-create the targets so we can compare via EvalSymlinks (TempDir on
292		// macOS lives under /private/var/... but is reported as /var/...).
293		if err := os.MkdirAll(filepath.Join(mainRoot, ".entire"), 0o755); err != nil {
294			t.Fatalf("MkdirAll: %v", err)
295		}
296		if err := os.MkdirAll(filepath.Join(worktreeDir, "src"), 0o755); err != nil {
297			t.Fatalf("MkdirAll: %v", err)
298		}
299	
300		entireAbs, err := AbsPath(ctx, ".entire/settings.json")
301		if err != nil {
302			t.Fatalf("AbsPath(.entire/settings.json): %v", err)
303		}
304		wantEntireDir := mustEvalSymlinks(t, filepath.Join(mainRoot, ".entire"))
305		if got := mustEvalSymlinks(t, filepath.Dir(entireAbs)); got != wantEntireDir {
306			t.Errorf("AbsPath(.entire/settings.json) parent = %q, want %q", got, wantEntireDir)
307		}
308	
309		// Non-entire relative paths must still anchor at the current worktree.
310		srcAbs, err := AbsPath(ctx, "src/main.go")
311		if err != nil {
312			t.Fatalf("AbsPath(src/main.go): %v", err)
313		}
314		wantSrcDir := mustEvalSymlinks(t, filepath.Join(worktreeDir, "src"))
315		if got := mustEvalSymlinks(t, filepath.Dir(srcAbs)); got != wantSrcDir {
316			t.Errorf("AbsPath(src/main.go) parent = %q, want %q", got, wantSrcDir)
317		}
318	
319		// Absolute inputs are returned unchanged regardless of prefix.
320		absIn := filepath.Join(mainRoot, ".entire", "x")
321		absOut, err := AbsPath(ctx, absIn)
322		if err != nil {
323			t.Fatalf("AbsPath(absolute): %v", err)
324		}
325		if absOut != absIn {
326			t.Errorf("AbsPath(%q) = %q, want unchanged", absIn, absOut)
327		}
328	}
