330	func initSeedRepo(t *testing.T) string {
331		t.Helper()
332		root := t.TempDir()
333		runGit(t, root, "init", "-q", "-b", "main", ".")
334		runGit(t, root, "config", "user.email", "test@example.com")
335		runGit(t, root, "config", "user.name", "Test")
336		runGit(t, root, "config", "commit.gpgsign", "false")
337		// At least one commit is required before `git worktree add -b` will succeed.
338		if err := os.WriteFile(filepath.Join(root, "README.md"), []byte("seed\n"), 0o644); err != nil {
339			t.Fatalf("WriteFile: %v", err)
340		}
341		runGit(t, root, "add", "README.md")
342		runGit(t, root, "commit", "-q", "-m", "seed")
343		return root
344	}
345	
346	func runGit(t *testing.T, dir string, args ...string) {
347		t.Helper()
348		cmd := exec.CommandContext(t.Context(), "git", args...)
349		cmd.Dir = dir
350		if out, err := cmd.CombinedOutput(); err != nil {
351			t.Fatalf("git %v in %s: %v\n%s", args, dir, err, out)
352		}
353	}
354	
355	func mustEvalSymlinks(t *testing.T, p string) string {
356		t.Helper()
357		r, err := filepath.EvalSymlinks(p)
358		if err != nil {
359			t.Fatalf("EvalSymlinks(%q): %v", p, err)
360		}
361		return r
362	}
