func (s *ManualCommitStrategy) postCommitUpdateBaseCommitOnly(ctx context.Context, head *plumbing.Reference) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	worktreePath, err := paths.WorktreeRoot(ctx)
