1433	// postCommitUpdateBaseCommitOnly updates BaseCommit for all sessions on the current
1434	// worktree when a commit has no Entire-Checkpoint trailer. This prevents BaseCommit
1435	// from going stale, which would cause future PrepareCommitMsg calls to skip the
1436	// session (BaseCommit != currentHeadHash filter).
1437	//
1438	// Unlike the full PostCommit flow, this does NOT fire EventGitCommit or trigger
1439	// condensation — it only keeps BaseCommit in sync with HEAD.
1440	func (s *ManualCommitStrategy) postCommitUpdateBaseCommitOnly(ctx context.Context, head *plumbing.Reference) {
1441		logCtx := logging.WithComponent(ctx, "checkpoint")
1442		worktreePath, err := paths.WorktreeRoot(ctx)
1443		if err != nil {
1444			return // Silent failure — hooks must be resilient
1445		}
1446	
1447		sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
1448		if err != nil || len(sessions) == 0 {
1449			return
1450		}
1451	
1452		newHead := head.Hash().String()
1453		for _, state := range sessions {
1454			// Only update active sessions. Idle/ended sessions are kept around for
1455			// LastCheckpointID reuse and should not be advanced to HEAD.
1456			if !state.Phase.IsActive() {
1457				continue
1458			}
1459			if state.BaseCommit != newHead {
1460				logging.Debug(logCtx, "post-commit (no trailer): updating BaseCommit and AttributionBaseCommit",
1461					slog.String("session_id", state.SessionID),
1462					slog.String("old_base", truncateHash(state.BaseCommit)),
1463					slog.String("new_head", truncateHash(newHead)),
1464				)
1465				state.BaseCommit = newHead
1466				// Keep AttributionBaseCommit in sync to prevent stale base drift.
1467				// Without this, a subsequent condensation would diff from the old base,
1468				// inflating human_added with lines from unrelated prior commits.
1469				state.RealignAttributionBase(newHead)
1470				if err := s.saveSessionState(ctx, state); err != nil {
1471					logging.Warn(logCtx, "failed to update session state",
1472						slog.String("session_id", state.SessionID),
1473						slog.String("error", err.Error()))
1474				}
1475			}
1476		}
1477	}
1478	
1479	// truncateHash safely truncates a git hash to 7 chars for logging.
1480	func truncateHash(h string) string {
1481		if len(h) > 7 {
1482			return h[:7]
1483		}
1484		return h

